answer.content:
.flex-container {
  display: flex;
  /* Sets main axis to horizontal (left-to-right) */
  flex-direction: row;
}

.flex-container-stacked {
  display: flex;
  /* Sets main axis to vertical (top-to-bottom) */
  flex-direction: column;
  gap: 16px;
}

.layout-wrapper {
  display: flex;
}

.sidebar {
  /* flex: grow shrink basis */
  /* Does not grow (0), shrinks if needed (1), base width 260px */
  flex: 0 1 260px;
  background-color: #f1f5f9;
}

.main-content {
  /* Grows to consume all remaining space (1), can shrink (1), base width 0 */
  flex: 1 1 0%;
  padding: 24px;
}

.hero-viewport {
  display: flex;
  /* Centers items along the main horizontal axis */
  justify-content: center;
  /* Centers items along the cross vertical axis */
  align-items: center;

  min-height: 100vh;
  background-color: #0f172a;
}

.hero-card {
  width: 90%;
  max-width: 480px;
  background-color: #ffffff;
  padding: 32px;
  border-radius: 12px;
}

.photo-gallery {
  display: grid;
  /* Creates 3 columns: first takes 250px, remaining space split into 2 equal fractions */
  grid-template-columns: 250px 1fr 1fr;
  /* Defines 20px gap between both rows and columns */
  gap: 20px;
}

/* Responsive auto-fit track pattern */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
}

.app-layout {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-rows: 60px 1fr 50px;
  grid-template-areas:
    "header  header"
    "sidebar content"
    "footer  footer";
  min-height: 100vh;
}

.site-header  { grid-area: header; background: #1e293b; color: white; }
.site-sidebar { grid-area: sidebar; background: #f8fafc; }
.site-content { grid-area: content; padding: 24px; }
.site-footer  { grid-area: footer; background: #e2e8f0; }
